-- Questões originais de estudo: Deitel e Deitel, Java: como programar, 10ª edição.
-- Tradução brasileira do PDF fornecido: Pearson Education do Brasil, 2017.
-- Contexto dos recursos: Java SE 8. Não são questões oficiais nem exercícios transcritos.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas são do arquivo PDF, não da numeração impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 24: Acesso a bancos de dados com JDBC — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('27e9c84c-5639-5930-8591-f5e555e9db15', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Um driver JDBC permite principalmente:', '["Criar interfaces gráficas.","Eliminar autenticação.","A comunicação entre aplicação Java e um SGBD compatível.","Compilar SQL em Java-fonte.","Substituir qualquer banco por memória local."]'::jsonb, 2, 'O driver adapta a interface JDBC ao sistema de dados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.1, páginas 850 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1ea72968-676a-5180-8d6b-b57086c8fb03', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Qual interface representa uma conexão JDBC?', '["Thread.","Graphics.","Path.","Scanner.","Connection."]'::jsonb, 4, 'A conexão delimita o contexto de interação com o banco.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.6, páginas 864–876 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fd63b739-d9d9-5300-ac2e-28d8af3f89fe', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'DriverManager.getConnection retorna normalmente:', '["Uma Connection.","Um File.","Um JFrame.","Uma List obrigatória.","Um ResultSet diretamente."]'::jsonb, 0, 'O estabelecimento da conexão pode falhar com SQLException.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.6, páginas 864–876 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fd0d1dca-59e1-54f9-a6e3-aae1de7ff10c', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'Statement.executeQuery é apropriado para instruções que retornam:', '["Um arquivo compilado.","Um ResultSet de consulta.","Um objeto Graphics.","Sempre um boolean de autenticação.","Somente número de linhas alteradas."]'::jsonb, 1, 'A operação é usada tipicamente com SELECT.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.6, páginas 864–876 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9430f290-0981-5ac6-b2e3-d10d96abf6f0', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'ExecuteUpdate em JDBC retorna tipicamente:', '["Sempre um ResultSet.","Uma contagem de linhas afetadas ou zero conforme a instrução.","Uma thread.","Uma String com todos os dados.","Um novo driver."]'::jsonb, 1, 'É usado para alterações e instruções compatíveis sem resultado tabular.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.6, páginas 864–876 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cc8c9ff4-380f-5b93-b0fc-fd20f3a5ef77', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Um cursor ResultSet começa normalmente:', '["Antes da primeira linha.","Na última linha.","Depois da última sempre.","Na primeira coluna da primeira linha já válida.","Em uma linha aleatória."]'::jsonb, 0, 'Next avança e informa se existe uma linha válida.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.6, páginas 864–876 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a7c522e7-ab21-57d9-8538-08c6913169bc', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'ResultSet.next retorna:', '["Sempre true.","Uma Connection.","O próximo valor int diretamente.","Se o avanço encontrou outra linha válida.","O nome da tabela."]'::jsonb, 3, 'O boolean controla a iteração sobre os resultados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.6, páginas 864–876 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bc9eed87-e876-5f66-bde7-3d0ae6a221e1', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Difícil', 'Os índices de colunas JDBC começam normalmente em:', '["-1.","2.","Depende do nome da tabela.","0.","1."]'::jsonb, 4, 'Essa convenção difere da indexação dos arrays Java.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.6, páginas 864–876 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cb93dc7e-5a87-5146-a960-e0c0fa360adc', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'SQLException transporta informações úteis como:', '["A quantidade de construtores.","Uma cor RGB.","Somente o nome da classe pública.","O resultado sempre válido da consulta.","Mensagem, estado SQL e código de erro conforme o driver."]'::jsonb, 4, 'Falhas de acesso precisam de tratamento apropriado.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.6, páginas 864–876 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3099540a-800e-56c4-ac4d-79a7b2c12221', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'Fechar recursos JDBC é importante principalmente para:', '["Ordenar os resultados.","Apagar o driver.","Converter linhas em objetos automaticamente.","Liberar recursos da aplicação e do banco.","Garantir que a consulta nunca falhe."]'::jsonb, 3, 'Try-with-resources pode auxiliar nos tipos compatíveis.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.6, páginas 864–876 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b2556f12-3d49-50d7-9fb8-94434b111788', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'PreparedStatement permite separar:', '["A estrutura SQL e os valores dos parâmetros.","As cores da interface.","O nome da classe e o arquivo-fonte.","Os threads da JVM.","As chaves de um Map apenas."]'::jsonb, 0, 'Valores são vinculados em posições parametrizadas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.8, páginas 879–891 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ada2a6df-2ac5-5bf7-8eda-bddb9e028ba7', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'No SQL de PreparedStatement, parâmetros de valor são marcados normalmente por:', '[":int obrigatório em JDBC puro.","%d como em printf.","# obrigatório.","@FXML.","?."]'::jsonb, 4, 'A vinculação posterior fornece os valores correspondentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.8, páginas 879–891 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ee49dd5c-49bc-5a81-9808-1770ed387de4', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'O primeiro parâmetro de PreparedStatement é referenciado por índice:', '["2.","O tamanho da consulta.","1.","0.","-1."]'::jsonb, 2, 'Os índices de parâmetros também usam base um.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.8, páginas 879–891 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7b8aa285-f51a-5e3b-9b08-8b9ba924098c', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'Concatenar entrada diretamente ao SQL aumenta o risco de:', '["Herança múltipla.","Boxing obrigatório.","Uma exceção de desenho.","Alterar a estrutura da consulta por injeção.","Coleta de lixo antecipada."]'::jsonb, 3, 'Parâmetros de valores ajudam a separar dados e instrução.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.8, páginas 879–891 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bb08399a-5a25-5ae2-ac9a-00314e4bce12', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Difícil', 'Um marcador de parâmetro de valor substitui diretamente qualquer nome de tabela?', '["Somente em SELECT.","Somente se a tabela estiver vazia.","Sim, se o nome for String.","Não.","Sim, sempre."]'::jsonb, 3, 'Identificadores e estrutura SQL exigem tratamento diferente dos valores vinculados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.8, páginas 879–891 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('767628f6-2302-5534-a807-8876af2085b3', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'CallableStatement é associado principalmente a:', '["Iteração de ArrayList.","Chamada de procedimentos armazenados.","Leitura de teclado.","Definição de interfaces funcionais.","Desenho de gráficos."]'::jsonb, 1, 'O capítulo distingue chamadas de rotinas das instruções preparadas comuns.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.9, páginas 892–893 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ce3142bd-292c-50f1-a534-87ae775fe29d', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Difícil', 'Para agrupar comandos em uma transação manual, pode-se primeiro usar:', '["close() em cada linha.","setAutoCommit(false).","next() antes de conectar.","getMetaData() como confirmação.","setAutoCommit(true) como garantia de agrupamento."]'::jsonb, 1, 'O programa passa a coordenar commit ou rollback da unidade.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.10, páginas 892–893 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3f086f36-1401-5352-b25a-250f7a757a77', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Difícil', 'Connection.commit confirma:', '["Um novo driver.","Toda transação de qualquer usuário.","A transação corrente naquela conexão.","O código-fonte Java.","Somente a última coluna lida."]'::jsonb, 2, 'O escopo transacional precisa ser compreendido no contexto da conexão.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.10, páginas 892–893 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f86b33c6-d40f-5e7f-b133-809c22302bea', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'Connection.rollback permite normalmente:', '["Desfazer alterações não confirmadas da transação corrente.","Desfazer qualquer commit histórico.","Excluir o driver.","Reiniciar a JVM.","Apagar o esquema sempre."]'::jsonb, 0, 'Rollback não é um mecanismo geral de desfazer transações já confirmadas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.10, páginas 892–893 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c1b8a3ac-1bcb-5539-a272-ecc546a600e8', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'Um CachedRowSet pode ser usado em estilo:', '["Somente com imagens.","Exclusivamente na thread gráfica.","Desconectado durante parte de sua manipulação.","Sem qualquer coluna.","Sem jamais obter dados de fonte."]'::jsonb, 2, 'A desconexão não elimina a necessidade de tratar sincronização e conflitos conforme o uso.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 24, seção 24.7, páginas 877–878 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
